local CatHouseResultEstimateFormulaContentNode = Class('CatHouseResultEstimateFormulaContentNode')

------------ import ------------
local KTool       = CS.Engine.Lib.KTool
---@type CatHouseMgr
local CatHouseMgr = import('Game.CatHouse.CatHouseMgr')
------------ import ------------

------------ define ------------
local checkNumber = checkNumber
local CellEnvPath                    = "Game.CatHouse.Interaction.CatHouseDataNode"
local CatHouseCaptureTextureComplete = Constants.EventNames.CatHouseCaptureTextureComplete

local Variation = 7 --- 对应 CatHouseResultEstimateDialog中 ShowGroupType.Variation
------------ define ------------

function CatHouseResultEstimateFormulaContentNode:__init()
end

function CatHouseResultEstimateFormulaContentNode:__delete()
end

function CatHouseResultEstimateFormulaContentNode:Awake()
    self.__EventCaptureTextureCompleteAction = Events.AddListener(CatHouseCaptureTextureComplete, Bind(self, self.OnEventCaptureTextureCompleteAction))

end

function CatHouseResultEstimateFormulaContentNode:OnDestroy()
    if self.__EventCaptureTextureCompleteAction then
        Events.RemoveListener(CatHouseCaptureTextureComplete, self.__EventCaptureTextureCompleteAction)
        self.__EventCaptureTextureCompleteAction = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象 self:Delete()
    self:Delete()
    self = nil
end


