---FreshUI
function CatHouseResultEstimateFormulaContentNode:FreshUI(data, name, showGroupType, myCatData, otherCatData)
    
    local isShowContent    = showGroupType < Variation
    self.TextTitle.text    = localize("_name_公式", {_name_ = name})
    self.ImgBgTitle.Status = isShowContent and 1 or 2

    KTool.SetActive(self.Content.gameObject, isShowContent)
    KTool.SetActive(self.None.gameObject,    not isShowContent)
    if isShowContent then
        self:FreshContent(data, name, showGroupType, myCatData, otherCatData)
    else
        self.NoneText.text = localize("_name_不会遗传", {_name_ = name})
    end
    
end

function CatHouseResultEstimateFormulaContentNode:FreshContent(data, name, showGroupType, myCatData, otherCatData)
    local myCatGene, otherCatGene = data.myCatGene, data.otherCatGene
    local isExistsMyCatGene       = myCatGene ~= nil
    local isExistsOtherCatGene    = otherCatGene ~= nil

    --- 写死路径 icon在<猫咪数据表>中 由于可能出现 两个猫都没有对于部位的情况 所以 路径直接写死
    -- Arts/Icons/CatHome/cathouse_data_icon_0.png
    self.TitleImgIcon:LoadSprite(string.format("Arts/Icons/CatHome/cathouse_data_icon_%s.png", showGroupType))

    self:FreshHead(myCatData, otherCatData)

    KTool.SetActive(self.Data1NoneData, not isExistsMyCatGene)
    if isExistsMyCatGene then
        self:FreshDataNode(self.Data1, myCatGene)

    end

    KTool.SetActive(self.Data2NoneData, not isExistsOtherCatGene)
    if isExistsOtherCatGene then
        self:FreshDataNode(self.Data2, otherCatGene)
        
    end
end

function CatHouseResultEstimateFormulaContentNode:FreshHead(myCatData, otherCatData)
    local catHouseMgr = CatHouseMgr:GetInstance()

    local attributes = catHouseMgr:GetAttributes(myCatData.genes)
    self.fileNameId1 = catHouseMgr:GetFileNameId(myCatData.age, myCatData.catId, attributes)    
    catHouseMgr:CaptureTexture(myCatData.age, myCatData.catId, attributes, false, self.fileNameId1)

    attributes = catHouseMgr:GetAttributes(otherCatData.genes)
    self.fileNameId2 = catHouseMgr:GetFileNameId(otherCatData.age, otherCatData.catId, attributes)    
    catHouseMgr:CaptureTexture(otherCatData.age, otherCatData.catId, attributes, false, self.fileNameId2)

    -- self.fileNameId1 = catHouseMgr:CaptureTexture(checkNumber(myCatData.age), myCatData.catId, catHouseMgr:GetAttributes(myCatData.genes)) 
    -- self.fileNameId2 = catHouseMgr:CaptureTexture(checkNumber(otherCatData.age), otherCatData.catId, catHouseMgr:GetAttributes(otherCatData.genes)) 

end

function CatHouseResultEstimateFormulaContentNode:FreshDataNode(dataNode, data)
    ---@type CatHouseDataNode
    local nodeEnv = CfUtils.GetLuaScr(dataNode, CellEnvPath)
    if not isNull(nodeEnv) then
        local geneId = data.id
        local geneData = {geneId = geneId}
        nodeEnv:FreshChild(geneData)
        nodeEnv:SetBtnCallBack(function ()
            CatHouseMgr:GetInstance():ShowCatHousDataDetailsNode(dataNode.gameObject, geneData)
        end)
    end
end

