function CatHouseResultEstimateFormulaContentNode:OnEventCaptureTextureCompleteAction(id, path)
    if self.fileNameId1 == id then 
        local texture = CatHouseMgr:GetInstance():LoadCaptureTexture(path)
        self.Data1ImgIcon.texture = texture
    elseif self.fileNameId2 == id then
        local texture = CatHouseMgr:GetInstance():LoadCaptureTexture(path)
        self.Data2ImgIcon.texture = texture
    end

end

